repo_files.ast_nodes.py:
"""AST node representations."""

from dataclasses import dataclass, field
from typing import Any, List, Optional


@dataclass
class ASTNode:
    pass


@dataclass
class VarNode(ASTNode):
    name: str


@dataclass
class AssignNode(ASTNode):
    target: str
    value: Any


@dataclass
class FunctionDefNode(ASTNode):
    fn_name: str
    params: List[str]
    body: List[ASTNode] = field(default_factory=list)

repo_files.symbol_table.py:
"""Hierarchical lexical scope symbol table."""

from typing import Dict, Optional


class Scope:
    def __init__(self, parent: Optional["Scope"] = None):
        self.parent = parent
        self.bindings: Dict[str, str] = {}

    def define(self, name: str, alias: str) -> None:
        self.bindings[name] = alias

    def lookup(self, name: str) -> Optional[str]:
        if name in self.bindings:
            return self.bindings[name]
        if self.parent:
            return self.parent.lookup(name)
        return None

repo_files.rewriter.py:
"""AST alpha-renaming rewriter."""

from typing import List
from ast_nodes import ASTNode, AssignNode, FunctionDefNode, VarNode
from symbol_table import Scope


class ASTAlphaRewriter:
    def rewrite(self, node: ASTNode, current_scope: Scope) -> ASTNode:
        if isinstance(node, VarNode):
            mapped = current_scope.lookup(node.name)
            return VarNode(mapped if mapped else node.name)

        elif isinstance(node, AssignNode):
            mapped = current_scope.lookup(node.target)
            val = node.value
            if isinstance(val, ASTNode):
                val = self.rewrite(val, current_scope)
            return AssignNode(mapped if mapped else node.target, val)

        elif isinstance(node, FunctionDefNode):
            # BUG: Reuses current_scope directly instead of creating a child Scope(parent=current_scope)
            # Shadowed parameters overwrite parent bindings in current_scope!
            for p in node.params:
                current_scope.define(p, f"{node.fn_name}_{p}")
            new_body = [self.rewrite(stmt, current_scope) for stmt in node.body]
            return FunctionDefNode(node.fn_name, [f"{node.fn_name}_{p}" for p in node.params], new_body)

        return node

reference_fix.rewriter.py:
"""AST alpha-renaming rewriter."""

from typing import List
from ast_nodes import ASTNode, AssignNode, FunctionDefNode, VarNode
from symbol_table import Scope


class ASTAlphaRewriter:
    def rewrite(self, node: ASTNode, current_scope: Scope) -> ASTNode:
        if isinstance(node, VarNode):
            mapped = current_scope.lookup(node.name)
            return VarNode(mapped if mapped else node.name)

        elif isinstance(node, AssignNode):
            mapped = current_scope.lookup(node.target)
            val = node.value
            if isinstance(val, ASTNode):
                val = self.rewrite(val, current_scope)
            return AssignNode(mapped if mapped else node.target, val)

        elif isinstance(node, FunctionDefNode):
            inner_scope = Scope(parent=current_scope)
            for p in node.params:
                inner_scope.define(p, f"{node.fn_name}_{p}")
            new_body = [self.rewrite(stmt, inner_scope) for stmt in node.body]
            return FunctionDefNode(node.fn_name, [f"{node.fn_name}_{p}" for p in node.params], new_body)

        return node
